add_action( 'woocommerce_after_shop_loop_item_title', 'perfectpixel_short_description_in_loop', 15 );

function perfectpixel_short_description_in_loop() {
	global $product;
	if ( ! $product ) {
		return;
	}
	$text = wp_strip_all_tags( strip_shortcodes( $product->get_short_description() ) );
	if ( '' === trim( $text ) ) {
		return;
	}
	echo '<p class="perfectpixel-loop-excerpt" style="font-size:.85em;margin:.25em 0 .75em">' . esc_html( wp_trim_words( $text, max( 3, (int) '{{loop_excerpt_words}}' ) ) ) . '</p>';
}
